      blue:["#fff9e4","#e8eddf","#c8d9d7","#a4bbc5","#fffced"],
      dusk:["#ba858a","#786079","#594d67","#49475f","#d39890"],
      dark:["#526071","#354454","#293b4c","#243545","#687485"],
