      const s=Math.min(hinge,end),len=Math.abs(end-hinge);
      if(street&&rise>.1)poly([[-5.69,hinge],[5.69,hinge],[5.69+rise*.46,end-rise*.34],[-5.69+rise*.46,end-rise*.34]],"rgba(39,61,56,.24)");
