      for(let u=-w*.34;u<w*.5;u+=w*.33) f.face(u,h*.5,front+.05,.38,h-.3,trim);
      f.box(0,h+1.55,-1,w*.68,2.5,d*.69,body);
      f.box(0,h+3,-1,w*.69,.47,d*.70,trim);
