    model(body,g=>fixedCar(g,id,s,occupied));
    const pitch=v.pitch||0,lean=v.lean||0,yaw=v.yaw||0;
    list.push([body,v.x,ground,v.z,yaw,pitch,lean]);
    if(!occupied)return;
