    const [x,y,z]=elbowAt(s),py=y*Math.cos(pitch)-z*Math.sin(pitch),pz=y*Math.sin(pitch)+z*Math.cos(pitch);
    const px=x*Math.cos(lean)-py*Math.sin(lean),p=BayDriving.world(v,px,pz);
