      if(name==='pool-pocket'){tone(effects,142,at,.12,gain,'triangle',68,.002);waterNoise(effects,at+.022,.062,gain*.60,780,280);}
      else if(name==='pool-rail'){tone(effects,240,at,.048,gain*.72,'triangle',122,.002);}
