    g.cyl(0,11.11,0,.12,.31,.15,8,ink);
    g.pole([0,11.17,0],[0,11.64,0],.023,rail,5);
    g.box(0,2.94,-1.37,.63,1.43,.092,ink);
    g.box(-.007,2.94,-1.427,.49,1.30,.045,"#59736d");
