      this.boat.phase="sail";this.sun=new BayHours.Clock(360);this.elapsed=0;this.age=0;
      this.speed=0;this.started=false;this.held=false;this.bump=0;this.result=null;
      this.landingAge=0;this.tieFrom=null;
