      if(night>.04)list.push(["court-flood-bulbs",s.x,s.y,s.z,s.yaw,0,0,.91*night]);
      if(!near)continue;
      const game=games?.find(g=>g.site?.id===s.id),swing=Math.max(0,Math.min(1,game?.net||0));
