      const speed=p.shot?(p.shot.stage==="wind"?.35:.15):p.stun>0?1.0:input.sprint?5.45:3.65;
      const target=n?Math.atan2(dx,dz):p.yaw,guard=h&&h!==p&&dist(h,p)<5.25;
