  function timeBand(weather={}){
    if(weather.rain>.44)return weather.night>.78?"night-rain":"rain";
    if(weather.night>.78)return "night";
    const minute=weather.minute??1030;
    return minute<480||minute>960?"twilight":"day";
  }
