    D:["04 00 20 41 43 24 04"],E:["40 00 04 44","02 32"],F:["40 00 04","02 32"],
    G:["40 10 01 03 14 44 42 22"],H:["00 04","02 42","40 44"],I:["20 24"],
    J:["40 43 34 14 03"],K:["00 04","40 02 44"],L:["00 04 44"],M:["04 00 22 40 44"],
