    R:["04 00 30 41 32 02","22 44"],S:["40 10 01 12 32 43 34 04"],T:["00 40","20 24"],
    U:["00 03 14 34 43 40"],V:["00 24 40"],W:["00 14 22 34 40"],X:["00 44","40 04"],
