      const sec=t-9.5,u=smooth((sec-.4)/4.6),boatX=208+sec*13;
      ripples(c,t,121);dock(c,-10,170,.95);ferry(c,boatX,169,.92,t);
      const x=mix(28,boatX+60,u),y=mix(152,148,u)-61*Math.sin(u*Math.PI);
