        const u=fan.age/fan.life,side=fan.side*(.12+(1-Math.pow(1-u,2))*(.9+3.6*fan.strength));
        const pos=BayDriving.world(fan,side,-Math.sign(fan.speed)*u*(.5+Math.abs(fan.speed)*.10));
