    g.box(.28,.367,-.053,.455,.235,.345,"#4a5450");g.box(.28,.491,-.053,.474,.019,.352,ink);
    g.box(.168,.51,-.041,.04,.018,.06,red);g.box(.398,.51,-.041,.04,.018,.06,metal);
    g.box(.28,.270,-.05,.536,.045,.40,red);
