    g.box(-.302,.348,0,.472,.196,.319,"#75695b");g.box(-.302,.451,0,.482,.029,.327,"#a09277");
    for(const x of [-.489,-.103])g.box(x,.361,.165,.029,.173,.012,"#5d5148");
