    for(let i=arm.first;i<arm.end;i+=6){
      const x=src[i],y=src[i+1],f=src[i+2];
      out[i]=bx+f*dx+x*ux+y*vx;out[i+1]=by+f*dy+y*vy;out[i+2]=bz+f*dz+x*uz+y*vz;
    }
