    if(cx>100){
      c.fillStyle="#658d91";c.beginPath();c.moveTo(w,0);
      for(let py=0;py<=h+12;py+=12){const z=cz+(h*.5-py)/scale;c.lineTo(x(z>180?BayCut.coast(z):213),py);}
      c.lineTo(w,h);c.closePath();c.fill();
    }
