/* starlite.js */
/* Gantry Street's open-air theatre. All timing is in simulated seconds. */
(() => {
  "use strict";
  const site={x:90,y:.096,z:-58,yaw:0},booth={x:84.17,z:-60.77,kind:"drive-in",name:"Starlite Motor Theatre"};
  const coast={id:"coast",title:"Coast Road, 1983",credit:"Soler family print · 16 mm",seconds:16};
  const ids=new Set(["coast","pelican","tram","windows","stunt","skate","edition","location","picture-jumps","rabbit","last-boat"]);
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function read(raw){
    const best={};
    for(const [id,n] of Object.entries(raw?.best||{}))if(ids.has(id)&&Number.isInteger(n)&&n>=1&&n<=100)best[id]=n;
    const tickets=(Array.isArray(raw?.tickets)?raw.tickets:[]).filter(t=>t&&ids.has(t.id)&&typeof t.title==="string"&&typeof t.plate==="string"&&typeof t.companion==="string"&&Number.isSafeInteger(t.day)&&t.day>0&&[1,2,3].includes(t.bay)).slice(-5);
    const p=raw?.park,park=p&&[p.x,p.z,p.yaw].every(Number.isFinite)&&Math.abs(p.x)<300&&Math.abs(p.z)<450?{x:p.x,z:p.z,yaw:p.yaw}:null;
    return {rev:Number.isSafeInteger(raw?.rev)&&raw.rev>=0?raw.rev:0,best,tickets,park,roof:raw?.roof===1?1:0,booked:ids.has(raw?.booked)?raw.booked:"coast"};
  }
  function bay(v){
    if(!v||Math.abs(v.speed)>.85||Math.cos(v.yaw)<.83||Math.abs(v.z-site.z)>2.15)return 0;
    return [-3.8,0,3.8].findIndex(x=>Math.abs(v.x-site.x-x)<.91)+1;
  }
  function fold(v,dt){
    if(Math.abs(v.speed)>3||v.softTop===v.roofTarget)return;
    v.softTop+=clamp(v.roofTarget-v.softTop,-dt/2.8,dt/2.8);
  }
  function wheelStop(v,priorZ){
    if(v.z<site.z-2||v.z>site.z+4||Math.abs(v.x-site.x)>5||v.vz<=0||v.speed>6.5||Math.cos(v.yaw)<.83)return;
    if(![-3.8,0,3.8].some(x=>Math.abs(v.x-site.x-x)<.87))return;
    const s=bayCarLayout(v.kind),lead=Math.max(...s.axles)*Math.cos(v.yaw)+Math.abs(Math.sin(v.yaw))*s.track;
    const limit=site.z+2.60-lead-.22;
    if(priorZ<=limit+.002&&v.z>limit){v.z=limit;v.vz=0;v.speed=v.vx*Math.sin(v.yaw);v.yawRate*=.8;}
  }
  class Theatre {
    constructor(){this.clock=0;this.run=null;this.visit=null;this.playFrom=0;this.variation=0;this.version=0;this.frameKey="";}
    show(program,booked){
      if(this.run?.dub)return {reel:BayLastBoat.reel,time:Math.min(this.run.dub.age,BayLastBoat.reel.seconds-.01),cue:""};
      if(this.visit?.family)return {reel:BayWalkHome.reel,time:Math.min(this.visit.age,BayWalkHome.reel.seconds-.1),cue:""};
      const bill=[coast,...program],r=this.run;
      if(r&&!r.done&&!r.switched){
        const reel=r.id==="coast"?program.find(f=>f.id==="pelican"):coast;
        return {reel,time:Math.min(reel.seconds-.1,reel.seconds-r.changeAt-.45+r.age),cue:r.cue};
      }
      let i=Math.max(0,bill.findIndex(f=>f.id===(this.onScreen||booked)));
      let time=Math.max(0,this.clock-this.playFrom)%bill.reduce((n,f)=>n+f.seconds,0);
      while(time>=bill[i].seconds){time-=bill[i].seconds;i=(i+1)%bill.length;}
      return {reel:bill[i],time,cue:""};
    }
    start(reel){
      this.visit=null;
      this.variation=(this.variation+1)%7;
      const motorAt=2.7+.23*this.variation;
      this.run={id:reel.id,title:reel.title,age:0,motorAt,changeAt:motorAt+3.35+.17*(this.variation%3),motor:0,started:false,switched:false,done:false,cue:"",score:0,feedback:""};
    }
    finish(r,score,message){r.done=true;r.cue="";r.score=score;r.feedback=message;return r;}
    input(code){
      const r=this.run;if(!r||r.done)return;
      if(code==="Space"&&!r.started){r.started=true;r.motorError=r.age-r.motorAt;r.motorTime=r.age;return;}
      if(code!=="KeyF")return;
      if(!r.started)return this.finish(r,0,"The second projector was still.");
      if(r.age-r.motorTime<1.25)return this.finish(r,0,"The second reel was still coming up to speed.");
      const error=r.age-r.changeAt,score=clamp(Math.round(100-28*Math.abs(r.motorError)-49*Math.abs(error)),0,100);
      if(score>=70){r.switched=true;this.onScreen=r.id;this.playFrom=this.clock;}
      const timing=(n)=>Math.abs(n)<.10?"on cue":Math.abs(n).toFixed(1)+" s "+(n<0?"early":"late");
      return this.finish(r,score,"Motor "+timing(r.motorError)+" · shutter "+timing(error));
    }
    step(dt){
      this.clock+=dt;const r=this.run;if(!r||r.done)return;
      if(r.dub){if(r.dub.step(dt)){r.done=true;return r;}return;}
      r.age+=dt;r.motor=r.started?clamp((r.age-r.motorTime)/1.25,0,1):0;
      r.cue=Math.abs(r.age-r.motorAt)<=.38?"motor":Math.abs(r.age-r.changeAt)<=.38?"change":"";
      if(r.age>r.changeAt+1.35)return this.finish(r,0,"The tail leader ran through the gate.");
    }
    frame(options,booked,projectedWidth,overhead=false){
      const program=BayCineProgram.describe(options),{reel,time,cue}=this.show(program,booked);
      // A drive-by projection can occupy fewer than fifty display pixels.
      // Sample the same film clock at twice its projected width or greater.
      const full=this.visit||this.run||!(projectedWidth>0);
      const width=full||projectedWidth>104?416:projectedWidth>72?208:144,height=width*9/16;
      const tick=Math.max(0,Math.floor(time*10)),key=reel.id+"/"+tick+"/"+cue+"/"+width;
      const bitmap=overhead&&typeof OffscreenCanvas!=="undefined"&&typeof OffscreenCanvas.prototype.transferToImageBitmap==="function";
      const take=this.run?.dub?.marks||options?.moonTake;
      const signature=reel.id==="last-boat"?(take?.join("/")||"silent"):"";
      if(this.frameKey===key&&this.frameSignature===signature&&this.frameBitmap===bitmap)return bitmap?this.print:this.canvas;
      const source=bitmap?(this.plate??=new OffscreenCanvas(width,height)):(this.canvas??=document.createElement("canvas"));
      if(source.width!==width)source.width=width;
      if(source.height!==height)source.height=height;
      const c=source.getContext("2d");
      c.save();c.scale(width/416,height/234);
      if(reel.id==="coast")BayCoastRoadFilm.paint(source,tick/10,width);
      else if(reel.id==="last-boat")BayLastBoat.film(c,this.run?.dub?.pier||options.moonPier,tick/10,take);
      else if(reel.id==="rabbit")BayWalkHome.movie(c,tick/10);
      else{
        let offset=0;for(const f of program){if(f.id===reel.id)break;offset+=f.seconds;}
        const frame=BayCineProgram.frame(offset+tick/10,options);
        if(frame.canvas)c.drawImage(frame.canvas,0,0,416,234);
      }
      if(cue){c.save();c.beginPath();c.arc(387,22,8,0,Math.PI*2);c.lineWidth=4;c.strokeStyle="#3a2923";c.stroke();c.lineWidth=2;c.strokeStyle="#ffefc8";c.stroke();c.restore();}
      if(this.run?.dub&&!this.run.done)BayLastBoat.leader(c,this.run.dub,tick/10);
      c.restore();this.frameKey=key;this.frameSignature=signature;this.frameBitmap=bitmap;this.version++;
      this.print?.close();this.print=bitmap?source.transferToImageBitmap():null;
      return this.print||this.canvas;
    }
  }
  window.BayStarlite={site,booth,coast,read,bay,fold,wheelStop,Theatre};
})();

;
/* ocean-beat.js */
/* Ocean Unit 12 works two curb posts. The officer, cruiser and signed copy
   keep their identity through an ordinary round, a traffic stop and a call. */
(() => {
  "use strict";
  const posts=[
    {x:137.85,z:-11.7,dir:2,yaw:Math.PI,name:"Ocean Drive",stand:{x:136.35,z:-16.3}},
    {x:5.35,z:48,dir:0,yaw:0,name:"Cine Luna",stand:{x:7.52,z:46.4}}
  ];
  const gap=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
  const approach=(a,b,dt)=>Math.abs(a-b)<.001?b:a+(b-a)*-Math.expm1(-7*dt);
  function read(raw){
    const s=raw?.slip;
    const valid=s&&["warning","citation","check"].includes(s.kind)&&Number.isSafeInteger(s.number)&&s.number>0&&
      ["car","plate","street"].every(k=>typeof s[k]==="string"&&s[k].length<90)&&
      Number.isInteger(s.minute)&&s.minute>=0&&s.minute<1440&&Number.isSafeInteger(s.day)&&s.day>0&&Number.isSafeInteger(s.fine)&&s.fine>=0&&s.fine<=25;
    return {known:!!raw?.known||!!valid,warnings:Number.isSafeInteger(raw?.warnings)&&raw.warnings>0?raw.warnings:0,slip:valid?{...s}:null};
  }
  function readRelease(s){
    if(s?.kind!=="release"||!Number.isSafeInteger(s.number)||s.number<1||!Number.isInteger(s.stars)||s.stars<1||s.stars>5||
      !Number.isFinite(s.fine)||s.fine<0||s.fine>65||typeof s.street!=="string"||!s.street.length||s.street.length>80||
      !Number.isInteger(s.minute)||s.minute<0||s.minute>=1440||!Number.isSafeInteger(s.day)||s.day<1)return null;
    const {kind,number,stars,fine,street,minute,day}=s;return {kind,number,stars,fine,street,minute,day};
  }
  class Round{
    constructor(v){
      this.v=v;this.post=0;this.phase="post";this.time=65;this.seat=0;this.walk=[];this.wait=0;this.stop=null;
      this.actor={...posts[0].stand,yaw:1.18,writing:0,give:0,motion:new BayPlayerMotion()};
      Object.assign(v,{beatCar:true,beatLights:false,serviceCar:true,plate:"OCEAN 12"});
    }
    standing(){return this.phase==="post";}
    window(v,side=-1){
      const p=BayCarAccess.outside(bayCarLayout(v.kind),side);return BayDriving.world(v,p.x,p.z);
    }
    walkTo(p,phase,e){
      const path=e.walk(this.actor,p);
      if(!path)return false;
      this.actor.motion.ride=null;this.walk=path;this.phase=phase;return true;
    }
    board(e){
      if(this.seat===1){this.phase="ready";return;}
      if(this.phase==="exit"||this.phase==="enter"){this.phase="enter";return;}
      if(!this.walkTo(this.window(this.v),"door",e)){this.phase="return";this.wait=.65;}
    }
    start(kind,target,e){
      if(this.stop||!target||target.serviceCar||!e.free()||!["round","post","toPost"].includes(this.phase))return false;
      const eye=this.seat===1?this.v:this.actor;
      if(kind==="check"?!this.canCheck(target,e):gap(eye,target)>44||!e.sees(eye,target))return false;
      this.stop={kind,target,origin:{x:target.x,z:target.z},brake:0};
      const v=this.v;
      v.beatLights=kind!=="check";this.wait=0;
      if(v.path&&v.speed>.3){v.pace=0;this.phase="stopping";}
      else{v.path=null;BayDriving.settle(v);this.phase="observe";}
      e.say(kind==="check"?"Both brake lamps, please. I’ll walk around back.":"I saw the bump. Find a curb and stop there a moment.");
      return true;
    }
    canCheck(v,e){return this.standing()&&v&&!v.serviceCar&&e.free()&&gap(v,this.actor)<12&&e.atCurb(v);}
    route(e){
      const v=this.v,next=posts[this.post^1],curb=e.curb(v);
      if(!curb){this.phase="ready";this.wait=1;return;}
      const path=BayCab.route({...curb,x:v.x,z:v.z},next).pts;
      Object.assign(v,{path,corner:1,finiteRoute:true,finiteYaw:next.yaw,pace:8.1,wait:0,blocked:0,wantsCurb:false,pullOver:null});
      this.post^=1;this.phase="round";v.beatLights=false;
    }
    cancel(e){
      this.stop=null;this.v.beatLights=false;this.board(e);
    }
    take(e){
      if(this.phase!=="paper"||!this.stop||e.driver()!==this.stop.target)return false;
      const {target,kind}=this.stop;this.stop=null;this.v.beatLights=false;this.board(e);
      e.file(target,kind);return true;
    }
    join(e){
      this.v.path=null;this.stop=null;this.v.beatLights=true;
      if(this.seat===1){this.phase="chase";e.dispatch(this.v);}
      else if(!["door","enter"].includes(this.phase))this.board(e);
    }
    release(e){
      if(this.phase==="chase"){e.release(this.v);this.phase="ready";this.wait=.8;}
      this.v.beatLights=false;
    }
    step(dt,e){
      const a=this.actor,v=this.v,s=this.stop;
      if(this.phase==="chase"){BayCarAccess.pose(v,-1,1,a,a.motion,e.ground,dt);return;}
      this.wait=Math.max(0,this.wait-dt);
      if(s){
        const abandoned=e.driver()!==s.target||!e.free()||gap(s.target,s.origin)>34;
        if(e.wanted()||abandoned){
          if(s.kind!=="check"&&e.driver()===s.target&&(e.wanted()||gap(s.target,s.origin)>34)){
            if(!e.wanted())e.call();this.join(e);
          }else this.cancel(e);
          return;
        }
        if(["rear","test","toWindow","write","paper"].includes(this.phase)&&(!e.atCurb(s.target)||gap(s.target,s.park)>1.15)){
          this.phase="observe";s.brake=0;this.walk=[];this.wait=.45;
        }
      }
      const walking=["toPost","door","rear","toWindow"].includes(this.phase);
      a.writing=approach(a.writing,this.phase==="write"?1:this.phase==="post"?.68:0,dt);
      a.give=approach(a.give,this.phase==="paper"?1:0,dt);
      if(walking){
        if(!BayCarAccess.walkPath(a,a.motion,this.walk,dt,e.ground,2.35))return;
        if(this.phase==="door")this.phase="enter";
        else if(this.phase==="toPost"){this.phase="post";this.time=41;a.yaw=posts[this.post].dir===2?1.18:-1.3;}
        else if(this.phase==="rear"){this.phase="test";e.say("Hold the brake. Let me see both lenses.");}
        else{this.phase="write";this.time=1.8;}
        return;
      }
      if(this.phase==="enter"||this.phase==="exit"){
        const entering=this.phase==="enter";this.seat=Math.max(0,Math.min(1,this.seat+(entering?1:-1)*dt/1.52));
        BayCarAccess.pose(v,-1,this.seat,a,a.motion,e.ground,dt);
        if(entering&&this.seat===1)this.phase="ready";
        if(!entering&&this.seat===0){a.motion.ride=null;this.phase=s?"observe":"arrived";}
        return;
      }
      if(this.seat===1)BayCarAccess.pose(v,-1,1,a,a.motion,e.ground,dt);else a.motion.step(dt,0,0);
      if(this.phase==="ready"){
        if(e.wanted()&&v.beatLights){this.join(e);return;}
        if(!this.wait)this.route(e);return;
      }
      if(this.phase==="round"){
        const post=posts[this.post];
        // A queue can fill the last car length of a curb post. Leave the
        // cruiser where it actually stopped if Solís can reach the sidewalk.
        if(v.path&&!this.wait&&v.corner===v.path.length-1&&v.blocked>2.4&&gap(v,post)<4.4&&e.atCurb(v)){
          this.wait=.8;
          if(e.walk(this.window(v),post.stand)){v.path=null;v.indicator=0;BayDriving.settle(v);}
        }
        if(!v.path)this.phase="exit";return;
      }
      if(this.phase==="return"){if(!this.wait)this.board(e);return;}
      if(this.phase==="arrived"){if(!this.wait&&!this.walkTo(posts[this.post].stand,"toPost",e))this.wait=1;return;}
      if(this.phase==="post"){this.time-=dt;if(this.time<=0&&!this.wait)this.board(e);return;}
      if(!s)return;
      const target=s.target;
      if(this.phase==="stopping"){
        if(!v.path||v.speed<.3){v.path=null;BayDriving.settle(v);this.phase="observe";}
        return;
      }
      if(this.phase==="observe"&&!this.wait&&e.atCurb(target)){
        if(this.seat===1){this.phase="exit";return;}
        s.park={x:target.x,z:target.z};
        const back=BayDriving.world(target,0,-bayCarLayout(target.kind).halfLength-.98);
        if(s.kind==="check"&&s.brake<1){
          if(!this.walkTo(back,"rear",e))this.wait=.8;
        }else if(!this.walkTo(this.window(target),"toWindow",e)&&!this.walkTo(this.window(target,1),"toWindow",e))this.wait=.8;
      }else if(this.phase==="test"){
        a.yaw=Math.atan2(target.x-a.x,target.z-a.z);
        s.brake=e.braking()&&target.brakes>.45?s.brake+dt:0;
        if(s.brake>=1){e.say("Left and right. Both good.");this.phase="observe";}
      }else if(this.phase==="write"||this.phase==="paper"){
        a.yaw=Math.atan2(target.x-a.x,target.z-a.z);this.time-=dt;
        if(this.phase==="write"&&this.time<=0){this.phase="paper";e.say(s.kind==="check"?"There you go. Both lamps signed off.":"Here’s your copy. Take care on Ocean.");}
      }
    }
  }
  window.BayOceanBeat={posts,read,readRelease,Round};
})();

