    g.tri([0,-.008,-l*.27],[0,0,-l*.45],[0,-r*.93,-l*.53],f.stripe);
    g.tri([0,r*.7,l*.16],[0,r*1.43,l*.02],[0,r*.70,-l*.18],f.stripe);
