      reel(list,model,cal,cal.yaw,hand(null,t));
      model("cork/cal-hat",g=>{g.cyl(0,.0,0,.218,.222,.024,12,"#c1a17a");g.cyl(0,.067,-.012,.136,.153,.121,10,"#b29571");g.cyl(0,.029,-.012,.151,.154,.026,10,green);});
