    shape([[-45,-3],[-23,-depth*.63],[-6,-depth],[9,-depth*.82],[31,-depth*.68],[55,-2],[60,2],[48,6],[17,depth],[-11,depth*.81],[-46,4]],f.color);
    shape([[-18,-depth*.68],[-11,-depth*1.42],[12,-depth*.83]],f.stripe);
