      const q={x,z,yaw,kind:v.kind,footprint:v.footprint};
      const deeper=o=>{const h=BayDriving.contact(q,o);return h&&h.depth>(BayDriving.contact(v,o)?.depth||0)+.00001;};
      if(deeper(this.engine)||deeper(this.van))return true;
