    for(let i=0;i<4;i++){const x=-181+i*35;if(!see({x:x+17.5,z:R.track(x)},142))continue;
      const k="belt/track"+i;model(k,g=>groundTrack(g,x,Math.min(-42,x+35)));list.push([k,0,0,0]);}
