      c.beginPath();c.arc(x+.04*s,y-.26*s,.115*s,0,2*Math.PI);c.fill();
      if(finished(b)){c.fillStyle="#788e87";c.fillRect(x-.20*s,y+(b.stage==="desk"?-.26:.08)*s,.2*s,.13*s);}
