      this.charge=null;
      if(d<.01||d>8.25)return false;
      this.flight={id:this.hand,start,end:{x:p.x+(r.x-p.x)*reach/d,z:p.z+(r.z-p.z)*reach/d},
        caught:Math.abs(reach-d)<=.85,distance:d,age:0,time:.42+.038*reach};
