      const c=side*.158;g.box(c,0,0,.315,.013,.37,"#f2e5c7");
      g.box(c,.010,.124,.245,.006,.035,"#865443");
      for(let i=0;i<4;i++)g.box(c,.010,.064-i*.053,i===3?.16:.245,.006,.014,"#686862");
