    card.setAttribute("aria-label","One Wheel distances. "+["paloma","heron"].map(k=>BayMotorcyclesArt.specs[k].name+" · "+(wheel[k]?wheel[k].metres.toFixed(1)+" metres":"open entry")).join(". "));
