      const wrong=BayValetPlaces.stalls.find(slot=>dist(v,slot)<3.8);
      if(wrong){const out=courtPoint(v.x,wrong.z-6.1);return [leg(v,[out],true),leg(out,[courtPoint(b.x,out.z),b])];}
