  function streetIncident(hits,vehicle){
    if(hits||!streetAction.report){addHeat(hits&&!heat?2:1);streetAction.report=4;}
    if(hits)for(const p of streetAction.lastFalls){
      // Choose a clear curb on the actual street, on the rear-door side of the response vehicle.
      const curb=rescueEnv.street(p);if(!curb)continue;
      const yaw=curb.yaw;
      for(const offset of [4.8,0,-4.8,8.5,-8.5]){
        const b={...curb,...BayDriving.world(curb,0,offset),kind:unit4.kind};
        if(!rescueEnv.carClear(unit4,b))continue;
        const rear=BayDriving.world(b,-.14,-4.55);
        if(!rescueEnv.cartLane(unit4,rear,p,vehicle?car:null))continue;
        if(rescue.requestStreet(p,vehicle?"traffic":"shots",BayStreetNames.through(b,yaw),b,personColors[p.style]))break;
      }
      if(rescue.pendingStreet)break;
    }
    if(hits&&!streetAction.witness){streetAction.witness=5;speak("Emergency dispatch",vehicle?"Person down. Caller saw the car.":"Shots reported. Send a unit and an ambulance.");}
  }
  function streetFire(){
    if(!streetAction.slot||!actionFeet())return false;
    const fired=streetAction.fire(hero,cameraRig.yaw,walkers,cars.concat(patrol),solids,footLevel);
    if(fired){hero.yaw=cameraRig.yaw;sound.cue(streetAction.slot===1?"street-sidearm":"street-scatter");streetIncident(fired.hits,false);lastHud=-10;}
    return true;
  }
  function actionPose(dt){
    if(flyingCopy?.walking&&flyingCopy.age<.47&&onStreetFeet()){
      const u=flyingCopy.age/.47,w=Math.sin(u*Math.PI);
      const reach=BayDriving.local(hero,flyingCopy.stop.x,flyingCopy.stop.z);
      motion.handTarget={paperToss:true,x:.18+clamp(reach.x,-.34,.34)*w,y:1.14+.33*w,z:.18+.36*w,weight:w};return;
    }
    if(motion.handTarget?.paperToss)motion.handTarget=null;
    const armed=streetAction.slot&&actionFeet();
    if(!armed){
      if(streetAction.slot)streetAction.equip(0);
      if(streetAction.wave>0&&onStreetFeet()){
        streetAction.wave=Math.max(0,streetAction.wave-dt);const reach=Math.min(1,(1.45-streetAction.wave)*5,streetAction.wave*4);
        hero.yaw+=angle(hero.yaw,Math.atan2(unit4.x-hero.x,unit4.z-hero.z))*-Math.expm1(-6*dt);
        motion.handTarget={streetWave:true,x:.26+.18*Math.sin(streetAction.wave*12),y:1.91,z:.19,weight:reach};
      }else{streetAction.wave=0;if(motion.handTarget?.streetGun||motion.handTarget?.streetWave)motion.handTarget=null;}
      return;
    }
    hero.yaw+=angle(hero.yaw,cameraRig.yaw)*-Math.expm1(-20*dt);
    motion.handTarget={streetGun:true,x:.22,y:1.22+streetAction.flash*.26,z:.44,weight:1};
  }
  function reportCrash(other,inward,closing){
    if(inward<4||closing<5.8||crashContacts.has(other))return;
    curbWire.bump(car,Math.min(inward,closing));
    crashContacts.set(other,true);
    if(active?.cabFare?.phase==="ride"&&active.cabFare.ride===car)active.cabFare.jolt++;
    if(!heat&&!beat.stop&&elapsed-lastIncident>25&&beat.start("warning",car,beatEnv)){
      lastIncident=elapsed;note("Ocean Unit 12","Pull over at a nearby curb for Officer Solís.",4);return;
    }
    if(!heat&&!beat.stop&&elapsed-lastIncident>25){
      lastIncident=elapsed;note("Traffic call","Driver reported the crash. Another wreck will bring patrol.",3.6);return;
    }
    const prior=heat;addHeat(1);
    if(prior<5&&heat===5)note("Bay Patrol","Air One, join the search.",3);
    else if(prior<4&&heat===4)note("Bay Patrol","Spike crews on standby.",3);
    else if(prior<3&&heat===3)note("Bay Patrol","Set up a roadblock on the next approach.",3);
    else note("Bay Patrol",!prior?"Multiple wrecks near "+district(pos())+". Units responding.":"Another collision called in.",3);
  }
