    if(active?.homeWalk){if(homeWalk.car)homeWalk.car.passengerDoor=0;homeWalk=new BayWalkHome.Walk(save.collection);}
    active?.payroll?.stop();
    if(active?.freight)spur.cancel();
    if(active?.featurePrint)active.featurePrint.ride.stop();
