  function stepRankPhones(){
    const at=pos(),available=!active&&!heat&&!room&&!needle&&!unit.eye&&!afternoon.photo;
    const event=rankPhones.scan(available?at:null,hours.total,hours.minute>=1020||hours.minute<120,available&&ringFoot());
    if(rankPhones.run&&!rankPhones.run.relay&&unit.lead!==rankPhones.run.lead){
      rankPhones.run.relay=true;rankPhones.save();
      speak(BaySecondUnit.names[rankPhones.run.lead],"I took the first call. Your clue is on the slip.");
    }
    const talk=rankPhones.talk;
    if(talk&&dist(talk.site,talk.actor)>3.4){
      if(talk.helper)talk.actor.motion.handTarget=null;
      rankPhones.talk=null;
    }
    else if(talk){
      const holding=talk.laundry?active?.laundry&&active.start!=null&&linenReach():talk.helper?talk.actor.phase==="wait"&&available&&streetTime<talk.until:
        rankPhones.near===talk.site&&ringFoot()&&(rankPhones.lifted||streetTime<talk.until);
      const age=Math.max(0,Math.min(.1,streetTime-talk.last));talk.last=streetTime;
      talk.amount=ease(talk.amount,holding?1:0,holding?9:13,age);
      if(talk.amount>.985||!holding)talk.passFrom=null;
      if(talk.helper){
        const a=talk.actor;
        if(holding)a.yaw+=angle(a.yaw,Math.atan2(talk.site.x-a.x,talk.site.z-a.z))*Math.min(1,7*age);
        a.motion.handTarget=holding?{receiver:true,x:.19,y:1.51,z:.12,weight:talk.amount}:null;
      }
      if(!holding&&talk.amount<.01)rankPhones.talk=null;
    }
    if(event==="expired"&&available)note("Ring Twice","The line went quiet. Pick up at any cab rank to try another call.",3.5);
    if(event!=="ring")return;
    const p=rankPhones.bell;
    sound.cue("rank-ring",{distance:dist(p,at)});
    for(const w of walkers)if(!w.onTour&&!w.neighborTalking&&!w.crossing&&dist(w,p)<6)w.ringLook={x:p.x,z:p.z,until:streetTime+1.12};
    if(rankPhones.rings>=3&&!rankPhones.run&&!rankPhones.talk){
      const helper=cabs.people.find(a=>a.phase==="wait"&&!a.ride&&dist(a,p)<1.7);
      if(!helper)return;
      rankPhones.talk={site:p,actor:helper,helper:true,last:streetTime,until:streetTime+7.5,amount:0};
      rankPhones.bell=null;rankPhones.silentUntil=hours.total+19;
      if(dist(hero,p)<11)speak(helper.name,"It's the station again. Here, you take this one.");
    }
  }
  function ringKey(code){
    if(code!=="KeyL"&&!(rankPhones.lifted&&/^(Digit|Numpad)[12]$/.test(code)))return false;
    if(!ringFoot()||!rankPhones.near||dist(hero,rankPhones.near)>=2.55)return false;
    if(code==="KeyL"){
      const event=rankPhones.answer(hours.total,unit.lead),info=BayRingTwice.streets[rankPhones.run.to];
      const prior=rankPhones.talk,from=prior?.helper?prior.actor:null;
      if(from)from.motion.handTarget=null;
      rankPhones.talk={site:rankPhones.near,actor:hero,amount:from?0:prior?.amount||0,last:streetTime,until:streetTime+2.15,
        passFrom:from?{...BayDriving.world(from,.19,.12),y:from.y+1.51}:null};
      if(event==="start"){saveTime();speak(info.caller,info.clue);}
      else if(event==="pick")speak(info.caller,"You got here. Pick one of the two sides for my dedication.");
      else speak(info.caller,(event==="wrong"?"Wrong line. Try this. ":"")+info.clue);
    }else{
      const reply=rankPhones.dedicate(Number(code.at(-1))-1,hours.total);if(!reply)return false;
      const track=BayAirwaves.records[reply.song],station=BayAirwaves.stations[track.station];
      saveTime();speak(reply.info.caller,reply.info.thanks);
      note("On "+station.frequency+" "+station.name,track.title+" · "+reply.mode+" "+reply.time.toFixed(1)+" s · Saved in J",4);
    }
    lastHud=-10;return true;
  }
  function rankPrompt(){
    const p=rankPhones,r=p.run,n=p.near;
    if(n&&ringFoot()){
      if(p.lifted){
        const songs=BayAirwaves.stations[BayRingTwice.streets[r.to].station].songs;
        return ["1 / 2",songs.map((id,i)=>(i+1)+" "+BayAirwaves.records[id].title).join("   ·   ")];
      }
      if(p.talk?.helper&&p.talk.site===n)return ["L","Take the receiver from "+p.talk.actor.name+" · F Bay Cab"];
      const label=r&&n.id===r.from?"Hear the clue again":r&&n.id!==r.to?"Check this line":r||p.bell?"Answer the payphone":"Call Ring Twice";
      return ["L",label+" · F Bay Cab"+(!unit.met&&crewPhoneNear()?" · Y Frankie":"")];
    }
    return null;
  }
  function nearNeedle(){
    return onStreetFeet()&&!active&&!heat&&!unit.eye&&!unit.transition&&!afternoon.photo&&!transit.engaged&&!cabs.booking&&
      Math.abs(hero.x-BayNeedle.site.x)<1.38&&hero.z<9.46&&dist(hero,BayNeedle.site)<2.45;
  }
  function needleSong(){
    const now=hours.total,fm=BayAirwaves;
    if(needleSide){
      const r=fm.records[needleSide.id],age=now-needleSide.at;
      if(age>=0&&age<r.bars*240/r.bpm)return {r,age};
    }
    const broadcast=fm.program("marea",now,save.airwaves);
    return {r:fm.records[broadcast.track],age:broadcast.age};
  }
  function chooseNeedleSide(){
    const id=needleChoices.shift();needleChoices.push(id);
    needleSide=BayNeedle.playSide(id,hours.total);saveTime();return BayAirwaves.records[id];
  }
  function newNeedleGame(){
    const current=needleSong().r.id;
    const found=BayOpenWindows.cards().map(c=>c.song.id);
    const singles=["mango-wire","dry-county","side-door","late-ferry","salt-chrome","after-hours"];
    needleChoices=[...new Set([...found,...singles])].filter(id=>id!==current).concat(current);
    needle=new BayNeedle.Table(BaySecondUnit.names[unit.lead],chooseNeedleSide);
    needleRecord=needle.record;
    keys.clear();resetPointer();motion.vx=motion.vz=0;hero.yaw=0;motion.step(0,0,0);
    $("pinCab").hidden=false;lastHud=-10;paintNeedle();
  }
  function leaveNeedle(){
    const record=needle.record,done=needle.phase==="over";needleRecord=record;needle=null;needleChoices=null;keys.clear();resetPointer();
    $("pinCab").hidden=true;lastHud=-10;cameraSnap();
    if(done)speak("Rae Cordero",record.best>2400?"Guess I need to take my own initials off the glass.":"Come back after my shift. I’ll show you the backhand off the left flipper.");
  }
  function needleInput(code){
    if(!needle){if(code!=="KeyF"||!nearNeedle())return false;newNeedleGame();return true;}
    if(code==="KeyE")leaveNeedle();
    else if(code==="Enter"&&needle.phase==="over")newNeedleGame();
    else if(code==="Escape")openPanel("pause");
    else if(code==="KeyR")radioToggle();
    else if(code==="ShiftLeft"||code==="ShiftRight")needle.nudge();
    else if(needle.phase==="pick"){
      if(code==="KeyA"||code==="ArrowLeft")needleChoices.unshift(needleChoices.pop());
      if(code==="KeyD"||code==="ArrowRight")needleChoices.push(needleChoices.shift());
      if(code==="KeyF"){needle.cueSide();keys.clear();}
    }
    else if(["KeyA","KeyD","ArrowLeft","ArrowRight"].includes(code))sound.cue("pin-flip");
    return true;
  }
  function paintNeedle(){
    const g=needle,song=g.phase==="pick"?BayAirwaves.records[needleChoices[0]]:needleSong().r,txt=(id,value)=>{if($(id).textContent!==value)$(id).textContent=value;};
    BayNeedleArt.glass($("pinGlass"),g);
    txt("pinScore",String(g.score).padStart(6,"0"));txt("pinBall","BALL "+g.ball+" / 3");
    txt("pinCall",g.phase==="pick"?"Pick a record with A / D. Press F to play it.":g.phase==="over"?"Game over · Enter to replay":g.phase==="drain"?"Ball in the trough":g.phase==="ready"?(g.held?"Release Space to launch":"Pull the plunger"):g.tilt?"TILT · Flippers cut until next ball":g.flash>0?"Three lit · New side on the speakers":g.lit?"Keep the lit records. Aim for the others.":"Hit the record bumpers");
    txt("pinLabel",g.phase==="pick"?"CHOOSE A SIDE":"ON THE SPEAKERS");
    txt("pinSong",song.title);txt("pinArtist",song.artist);
    const sleeve=$("pinSleeve");
    if(sleeve.dataset.track!==song.id){sleeve.getContext("2d").drawImage(BayNeedleArt.cover(song),0,0);sleeve.dataset.track=song.id;}
    txt("pinBest","House 2,400 · Rae"+(g.record.best?" / Best "+g.record.best.toLocaleString("en-US")+" · "+g.record.by:""));
  }
  function needleSpeaker(at,yaw){
    const s=BayNeedle.site,d=dist(at,s);
    if(room||swim||skiff||d>19||!needle&&!car&&!onStreetFeet())return carRadios.air;
    const gain=(1-d/19)**1.5*(car?.24:.70);
    if(carRadios.air&&carRadios.air.gain>gain)return carRadios.air;
    const {r,age}=needleSong();
    return {gain,pan:needle?0:clamp(((s.x-at.x)*Math.cos(yaw)-(s.z-at.z)*Math.sin(yaw))/Math.max(d,3),-.9,.9),
      cutoff:car?1550:3750,program:{decks:[{id:r.id,key:"arcade/"+r.id,tempo:r.bpm,beat:age*r.bpm/60,level:1}]}};
  }
  function curbVehicle(){return play&&car&&!transfer&&!active?.take&&!motos.finder&&!unit.eye&&!room&&!car.serviceCar?car:null;}
  const coffeeEnv={
    free:()=>freeFeet()&&!heat&&!active&&!unit.eye&&!unit.transition&&!roofs.raised&&!afternoon.photo&&!rainWalk.trip&&!windowRide&&!palm.playerSeat&&!broadcastDesk.mix,
    day:()=>hours.day+1,angle,say:line=>speak("Bea Serrano",line),
    approach:(path,dt)=>BayCarAccess.walkPath(hero,motion,path,dt,footLevel,1.7)
  };
  function cornerAction(use=false){
    if(!onStreetFeet()||!coffeeEnv.free())return "";
    const s=BayCrosswalk.button(BayStreetArt.signals,hero);
    if(coffeeEnv.free()){
      if(coffee.invited(hero)){
        if(use){coffee.join();if(s)BayCrosswalk.call(s,streetTime);speak("Bea Serrano",!coffee.cups?"I’ve got ten minutes off the desk. Walk over to the Palm with me? I’ll get the coffee.":coffee.lastDay===hours.day+1?"Back for a refill already? Come on, then.":"My usual walking partner. Two cups again?");}
        return "Walk to the Palm with Bea";
      }
      if(coffee.stage==="sip"){if(use)coffee.leave();return "Put the cup down";}
      if(coffee.nearCup(hero)&&(coffee.stage==="table"||!coffee.stage)){
        if(use){
          const table=BayPalmCoffee.site,via=[{x:table.x,z:table.z+1.0},{x:table.x,z:table.z-1.0}];
          const path=recoveryWalkway(hero,BayPalmCoffee.guest,null,via,cars.filter(c=>dist(c,table)<8));
          if(coffee.pour(path)){motion.vx=motion.vz=0;keys.clear();}
        }
        return coffee.stage==="table"?"Have coffee with Bea":"Have a cup at the Palm";
      }
    }
    if(s){
      const phase=BayCrosswalk.phase(s,streetTime);
      if(!use&&phase!=="idle")return phase==="walk"?"Walk light · Cross with the signal":phase==="finish"?"Flashing hand · Finish crossing":"Walk light requested";
      if(use&&BayCrosswalk.call(s,streetTime))note("Pedestrian signal","Call received. Watch the far corner for the walk figure.",2.1);
      return "Press the walk button";
    }
    return "";
  }
